<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Product,Brand,ProductCategory,Industry,Application,ProductAttribute};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class ProductController extends Controller {public function index(Request $r){$q=Product::with(['brand','category'])->search($r->q);return view('admin.products.index',['products'=>$q->latest()->paginate(20)->withQueryString()]);}public function create(){return view('admin.products.form',$this->lookups()+['product'=>new Product]);}public function store(Request $r){$p=Product::create($this->validated($r));$this->sync($r,$p);return redirect()->route('admin.products.edit',$p)->with('success','Product created.');}public function edit(Product $product){$product->load(['attributes','industries','applications']);return view('admin.products.form',$this->lookups()+compact('product'));}public function update(Request $r,Product $product){$product->update($this->validated($r,$product));$this->sync($r,$product);return back()->with('success','Product updated.');}public function destroy(Product $product){if($product->featured_image)Storage::disk('public')->delete($product->featured_image);$product->delete();return back()->with('success','Product deleted.');}
private function validated(Request $r,?Product $p=null):array{$d=$r->validate(['name'=>'required|max:255','slug'=>'nullable|max:255|unique:products,slug,'.($p?->id??'NULL'),'sku'=>'nullable|max:100|unique:products,sku,'.($p?->id??'NULL'),'model'=>'nullable|max:150','series'=>'nullable|max:150','brand_id'=>'nullable|exists:brands,id','category_id'=>'nullable|exists:product_categories,id','short_description'=>'nullable|max:2000','description'=>'nullable','technical_description'=>'nullable','availability'=>'required|max:50','seo_title'=>'nullable|max:255','seo_description'=>'nullable|max:1000','seo_keywords'=>'nullable|max:500','featured_image'=>'nullable|image|max:5120','featured'=>'nullable|boolean','status'=>'nullable|boolean']);$d['slug']=$d['slug']?:Str::slug($d['name']);$d['featured']=$r->boolean('featured');$d['status']=$r->boolean('status');if($r->hasFile('featured_image')){$d['featured_image']=$r->file('featured_image')->store('products','public');if($p?->featured_image)Storage::disk('public')->delete($p->featured_image);}return $d;}
private function sync(Request $r,Product $p):void{$p->industries()->sync($r->input('industries',[]));$p->applications()->sync($r->input('applications',[]));$p->attributes()->delete();foreach($r->input('attributes',[]) as $a){if(!empty($a['name'])&&isset($a['value']))ProductAttribute::create(['product_id'=>$p->id,'attribute_group'=>$a['group']??null,'attribute_name'=>$a['name'],'attribute_value'=>$a['value'],'unit'=>$a['unit']??null,'sort_order'=>$a['sort_order']??0]);}}
private function lookups():array{return ['brands'=>Brand::orderBy('name')->get(),'categories'=>ProductCategory::orderBy('name')->get(),'industries'=>Industry::orderBy('name')->get(),'applications'=>Application::orderBy('name')->get()];}}
